    private static int checks;
    private static final int LOCALS=0x2000f00c;
    private static final int[] WATCH={0x9d8a20,0x43d410,0x43d434,0xbb84e8,0x9b9f18,0xbb844c,0x43d418,0x9da4a4};
    private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    private static byte[] bytes(DataInput in)throws IOException{byte[] b=new byte[in.readInt()];in.readFully(b);return b;}
    private static int[] ints(DataInput in)throws IOException{int[] a=new int[in.readInt()];for(int n=0;n<a.length;n++)a[n]=in.readInt();return a;}
    private static final class Event {
        final String name;final int[] args,watch;
        Event(String name,int[] args,int[] watch){this.name=name;this.args=args;this.watch=watch;}
        Event(DataInput in)throws IOException{this(in.readUTF(),ints(in),ints(in));}
        public boolean equals(Object o){if(!(o instanceof Event))return false;Event e=(Event)o;return name.equals(e.name)&&Arrays.equals(args,e.args)&&Arrays.equals(watch,e.watch);}
        public int hashCode(){return name.hashCode();}
        public String toString(){return name+Arrays.toString(args)+Arrays.toString(watch);}
    }
    private static final class Snapshot {
        final int[] bases;final byte[][] bytes;final byte[] local;
        Snapshot(DataInput in)throws IOException{bases=ints(in);bytes=new byte[bases.length][];for(int n=0;n<bases.length;n++)bytes[n]=bytes(in);local=bytes(in);}
    }
    private static final class Memory implements Pc1TextProducer.State,Pc1TextExpander.LiveState {
        final byte[] raw=new byte[0x1000000];final BitSet known=new BitSet(raw.length);final Pc1Fetch.Frame frame;
        final Map<String,int[][]> mutations=new HashMap<>();final List<Event> events=new ArrayList<>();final List<int[]> reads=new ArrayList<>();
        final int failStore,failCall,skip,transition;final boolean unknownLocal;int stores,calls;
        Memory(DataInput in,Snapshot initial,int failStore,int failCall,int skip,int transition,boolean unknownLocal)throws IOException{
            this.failStore=failStore;this.failCall=failCall;this.skip=skip;this.transition=transition;this.unknownLocal=unknownLocal;
            int mutationCount=in.readInt();for(int n=0;n<mutationCount;n++){String name=in.readUTF();int[][] rows=new int[in.readInt()][3];for(int[] row:rows)for(int k=0;k<3;k++)row[k]=in.readInt();mutations.put(name,rows);}
            for(int n=0;n<initial.bases.length;n++){int base=initial.bases[n];System.arraycopy(initial.bytes[n],0,raw,base,initial.bytes[n].length);known.set(base,base+initial.bytes[n].length);}
            byte[] mask=new byte[initial.local.length];Arrays.fill(mask,(byte)1);frame=Pc1Fetch.Frame.fromKnown(initial.local,mask);
        }
        int at(int address)throws IOException{if(address<0||address>=raw.length||!known.get(address))throw new IOException("unowned fixture byte");return address;}
        public int read(int address)throws IOException{if(address>=0x440200&&address<0x440700)reads.add(new int[]{1,address});return raw[at(address)]&255;}
        public int readInt32(int address)throws IOException{int v=0;for(int n=0;n<4;n++)v|=read(address+n)<<(n*8);return v;}
        public void write(int address,int value)throws IOException{store(address,1,value&255);}
        public void writeInt32(int address,int value)throws IOException{store(address,4,value);}
        public void writeInt16(int address,int value)throws IOException{store(address,2,value&65535);}
        void store(int address,int size,int value)throws IOException{
            stores++;if(stores==failStore){events.add(new Event("fault",new int[]{address,size,value},new int[0]));throw new IOException("declared store");}
            for(int n=0;n<size;n++)at(address+n);for(int n=0;n<size;n++)raw[address+n]=(byte)(value>>>(n*8));events.add(new Event("store",new int[]{address,size,value},new int[0]));mutate("store"+stores);
        }
        void mutate(String name)throws IOException{int[][] rows=mutations.get(name);if(rows==null)return;for(int[] row:rows)for(int n=0;n<row[2];n++){int a=row[0]+n;if(a>=LOCALS&&a<LOCALS+Pc1Fetch.Frame.BYTES)frame.writeByte(a-LOCALS,row[1]>>>(8*n));else raw[at(a)]=(byte)(row[1]>>>(8*n));}}
        void event(String name,int...args)throws IOException{int[] watch=new int[WATCH.length];for(int n=0;n<watch.length;n++)watch[n]=readInt32(WATCH[n]);calls++;events.add(new Event(name,args,watch));if(calls==failCall)throw new IOException("declared leaf");mutate(name);}
        Pc1TextProducer producer()throws IOException{
            final Pc1TextExpander.LinkedCrt crt=new Pc1TextExpander.LinkedCrt(this){protected int classify423486(int value,int mask)throws IOException{event("locale",value,mask);throw new IOException("required locale");}};
            final Pc1TextExpander.Live expansion=new Pc1TextExpander.Live(this,new Pc1TextExpander.LiveServices(){
                public int atoi420BDA(Pc1GlyphCache.Source source)throws IOException{event("atoi");return crt.atoi420BDA(source);}
                public int isDigit420AD0(int signedByte)throws IOException{event("digit",signedByte);return crt.isDigit420AD0(signedByte);}
                public int variable411910(int bank,int index)throws IOException{event("variable",bank,index);return bank*1000+index;}
                public void sprintf420661(Pc1TextExpander.Local out,int format,int value)throws IOException{
                    event("sprintf",format,value);if(read(format)!='%'||read(format+1)!='d'||read(format+2)!=0)throw new IOException("required format");
                    byte[] b=(unknownLocal?"X":Integer.toString(value)).getBytes("US-ASCII");for(int n=0;n<b.length;n++)out.write(n,b[n]&255);if(!unknownLocal)out.write(b.length,0);
                }
            });
            return new Pc1TextProducer(this,new Pc1TextProducer.Services(){
                public void expand4123A0(Pc1GlyphCache.Source source,int dest)throws IOException{expansion.expand(source,dest);}
                public void release411080(int slot,int mode)throws IOException{event("release",slot,mode);}
                public void bake411D30()throws IOException{event("bake");}
                public int transition41A0B0(int target,int argument)throws IOException{event("transition",target,argument);return transition;}
                public int skip4118B0()throws IOException{event("skip");return skip;}
                public void stopVoice41CBE0()throws IOException{event("stop");}
                public void restoreControls412260(int mode)throws IOException{event("restore",mode);}
                public void activate412320()throws IOException{event("activate");}
                public void redraw418220(int selection)throws IOException{event("redraw",selection);}
            });
        }
    }
    public static int run()throws Exception{
        checks=0;Snapshot template=null;for(String encoded:VECTORS){
            DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded))));
            String name=in.readUTF();int op=in.readInt(),arg=in.readInt(),device=in.readInt(),failStore=in.readInt(),failCall=in.readInt(),skip=in.readInt(),transition=in.readInt();boolean unknownLocal=in.readBoolean();Snapshot initial=new Snapshot(in);if(template==null)template=initial;Memory m=new Memory(in,initial,failStore,failCall,skip,transition,unknownLocal);Snapshot expected=new Snapshot(in);
            int count=in.readInt();List<Event> events=new ArrayList<>();for(int n=0;n<count;n++)events.add(new Event(in));int[][] reads=new int[in.readInt()][2];for(int[] row:reads)for(int n=0;n<2;n++)row[n]=in.readInt();int expectedFlow=in.readInt();String expectedError=in.readUTF();check(in.read()==-1,"complete fixture "+name);
            Pc1TextProducer p=m.producer();boolean failed=false;Pc1TextProducer.Flow flow=Pc1TextProducer.Flow.COMMON_TAIL;
            Pc1GlyphCache.Source liveSource=offset->{m.reads.add(new int[]{0,offset});return m.frame.source().unsignedByte(offset);};
            try{if(op==0x4b)flow=p.speaker(liveSource);else if(op==0x4c)flow=p.body(m.frame::previousOpcode,liveSource);else if(op==7)flow=p.wait07(arg);else if(op==9)flow=p.wait09(device);else throw new AssertionError("op");}catch(IOException failure){failed=true;}
            p.requireBoundary();check(failed==!expectedError.isEmpty(),"native failure "+name+" expected="+expectedError);check(flow.ordinal()==expectedFlow,"direct-return/common-tail "+name);check(m.events.size()==events.size(),"ordered event count "+name+" actual="+m.events+" expected="+events);
            for(int n=0;n<events.size();n++)check(m.events.get(n).equals(events.get(n)),"exact event #"+n+" "+name+" actual="+m.events.get(n)+" expected="+events.get(n));
            check(m.reads.size()==reads.length,"source/CRT read count "+name+" actual="+m.reads.size()+" expected="+reads.length);for(int n=0;n<reads.length;n++)check(Arrays.equals(m.reads.get(n),reads[n]),"source/CRT exact read order #"+n+" "+name+" actual="+Arrays.toString(m.reads.get(n))+" expected="+Arrays.toString(reads[n]));
            for(int n=0;n<expected.bases.length;n++){int base=expected.bases[n];check(Arrays.equals(Arrays.copyOfRange(m.raw,base,base+expected.bytes[n].length),expected.bytes[n]),"whole native region0x"+Integer.toHexString(base)+" "+name);}
            check(Arrays.equals(m.frame.rawBytes(),expected.local),"same typed caller locals "+name);
        }
        boundaries(template);return checks;
    }
    private interface Work {void run()throws Exception;}
    private static void reject(Work work,String why)throws Exception{boolean failed=false;try{work.run();}catch(IOException expected){failed=true;}check(failed,why);}
    private static Memory clean(Snapshot template)throws IOException{return new Memory(new DataInputStream(new ByteArrayInputStream(new byte[4])),template,-1,-1,0,0,false);}
    private static void boundaries(Snapshot template)throws Exception{
        Memory a=clean(template);Pc1TextProducer pa=new Pc1TextProducer(a,null);reject(()->pa.speaker(a.frame.source()),"speaker requires exact expansion leaf");check(a.stores==0,"missing expansion leaves speaker untouched");
        Memory b=clean(template);Pc1TextProducer pb=new Pc1TextProducer(b,null);reject(()->pb.body(()->0,b.frame.source()),"body missing expansion after clear");check(b.stores==1&&b.events.get(0).args[0]==Pc1TextProducer.SPEAKER,"body required-leaf failure preserves exactly its head clear");
        Memory c=clean(template);Pc1TextProducer pc=c.producer();c.frame.unknownByte(Pc1Fetch.Frame.PREVIOUS);reject(()->pc.body(c.frame::previousOpcode,c.frame.source()),"unknown previous gates before any expansion or store");check(c.stores==0&&c.events.isEmpty(),"unknown previous has empty prefix");
        Memory d=clean(template);Pc1TextProducer pd=d.producer();d.frame.writeByte(Pc1Fetch.Frame.BUFFER,'A');d.frame.unknownByte(Pc1Fetch.Frame.BUFFER+1);reject(()->pd.speaker(d.frame.source()),"unknown next source gates at actual load");check(d.stores==1&&d.raw[Pc1TextProducer.SPEAKER]=='A',"known output precedes unknown next source; no fabricated terminator");
        Memory e=clean(template);Pc1TextExpander.Live pe=new Pc1TextExpander.Live(e,null);reject(()->pe.expand(offset->new int[]{'A','$','1',0}[offset],Pc1TextProducer.SPEAKER),"missing signed-digit leaf is required only when consumed");check(e.stores==1,"missing CRT preserves ordinary-byte prefix");pe.requireBoundary();
        Memory f=clean(template);final Pc1TextProducer[] pf={null};final boolean[] fenced={false};pf[0]=new Pc1TextProducer(f,new Pc1TextProducer.Services(){public void expand4123A0(Pc1GlyphCache.Source source,int at)throws IOException{try{pf[0].requireBoundary();}catch(IOException expected){fenced[0]=true;}throw new IOException("callee failure");}});reject(()->pf[0].speaker(f.frame.source()),"callee failure propagates");check(fenced[0],"snapshot forbidden during actual text native leaf");pf[0].requireBoundary();
    }
